Python implementation apps.api.app.api.routes.analysis.download_artifact: @router.get('/analysis/tasks/{task_id}/artifacts/{artifact_name}')
def download_artifact(task_id: str, artifact_name: str, session: Session=Depends(get_session)) -> FileResponse:
    try:
        artifact = _task_service(session).resolve_artifact(task_id, artifact_name)
    except (TaskNotFoundError, ArtifactNotFoundError, ArtifactFileNotFoundError) as exc:
        _raise_http_error(exc)
    artifact_path = artifact.path
    media_type = artifact.media_type
    content_disposition_type = 'inline' if media_type.startswith('text/html') else 'attachment'
    return FileResponse(artifact_path, filename=artifact_path.name, media_type=media_type, content_disposition_type=content_disposition_type)

